import { date, escapeHtml, money, number, percent } from './format';
import type { RenderedMarkdown } from './markdown';
import type { AdviceResult } from './rebalance';
import type { LocalPortfolio, PublicAsset, PublicSnapshot } from './types';
import { REGIME, sparkline, type PageId } from './ui';

export interface PageContext {
  page: PageId;
  root: string;
  snapshot: PublicSnapshot;
  portfolio: LocalPortfolio;
  advice: AdviceResult;
  model?: RenderedMarkdown;
}

function narrative(snapshot: PublicSnapshot): string {
  if (snapshot.health.blocking) return '数据质量门槛未通过。系统保留上一份已确认方案，不生成新的人工再平衡建议。';
  const risk = snapshot.risk;
  const trend = risk.trendBreadth >= .67 ? '权益趋势整体有支撑' : risk.trendBreadth >= .33 ? '权益趋势出现分化' : '多数权益趋势偏弱';
  const volatility = risk.volScore >= .9 ? '波动压力较低' : risk.volScore >= .65 ? '波动开始约束风险预算' : '波动压力显著';
  return `${trend}，${volatility}。模型把已确认权益目标控制在 ${percent(risk.confirmedEquityTarget)}；这是风险预算，不是涨跌预测。`;
}

function factor(title: string, weight: string, value: number, meaning: string, implication: string): string {
  return `<article class="factor reveal"><span class="factor-index">${weight}</span><div><div class="factor-title"><h3>${title}</h3><strong>${percent(value)}</strong></div><div class="track"><i style="width:${Math.max(0, Math.min(100, value * 100))}%"></i></div></div><p>${meaning}<strong>${implication}</strong></p></article>`;
}

function renderRisk(context: PageContext): string {
  const { snapshot, root } = context;
  const regime = REGIME[snapshot.risk.regime] ?? REGIME['DATA ERROR'];
  const score = Math.round((snapshot.risk.score ?? 0) * 100);
  return `<section class="risk-hero reveal"><div><p class="eyebrow">当前风险状态 · ${snapshot.meta.signalDate}</p><h1>${regime.zh}<span>${regime.copy}</span></h1><p class="lead">${escapeHtml(narrative(snapshot))}</p><div class="signal-stamp"><i></i><span><strong>${snapshot.meta.confirmedSignalDate} 月末已确认</strong> · 最早下一交易日使用</span></div></div>
      <div class="score"><div class="score-ring" style="--score:${score}"></div><div><strong>${score}</strong><span>全局风险评分 / 100</span></div></div></section>
    <section class="section"><div class="section-head reveal"><div><p class="eyebrow">LAYER 02 · 市场风险</p><h2>风险预算为何处于这里</h2></div><p>趋势看方向一致性，波动看风险成本，回撤看战略组合离高点的距离。三者都只使用已经发生的数据。</p></div>
      <div class="factor-list">
        ${factor('多周期趋势广度', '45%', snapshot.risk.trendBreadth, '三只权益 ETF 的 63 / 126 / 252 日趋势，按战略权益比例合并。', snapshot.risk.trendBreadth >= .5 ? ' 趋势仍在支撑风险预算。' : ' 趋势正在压低风险预算。')}
        ${factor('组合波动约束', '35%', snapshot.risk.volScore, `参考组合预测波动率为 ${percent(snapshot.risk.forecastVol)}，与目标波动率比较。`, snapshot.risk.volScore >= .8 ? ' 当前约束温和。' : ' 波动约束正在增强。')}
        ${factor('战略组合回撤', '20%', snapshot.risk.ddScore, `固定战略组合较过去 252 日高点回撤 ${percent(snapshot.risk.drawdown)}。`, snapshot.risk.ddScore >= .8 ? ' 回撤约束较弱。' : ' 组合需要更多防守。')}
      </div>
      <div class="history-band reveal"><div><span>近三年风险评分</span><strong>${percent(snapshot.risk.score)}</strong><small>连续分值，不是买卖开关</small></div>${sparkline(snapshot.history.map((item) => ({ value: item.riskScore })), '近三年全局风险评分曲线')}</div>
    </section>
    <section class="section compact"><div class="section-head reveal"><div><p class="eyebrow">从状态到行动</p><h2>本次信号的下一步</h2></div><p>正式风险目标已经确认，但只有在数据正常、持仓偏差越过免交易带后，才可能产生人工建议。</p></div>
      <div class="decision-path reveal"><div><span>01</span><strong>数据闸门</strong><p class="${snapshot.health.blocking ? 'negative' : 'positive'}">${snapshot.health.blocking ? '关闭' : '开放'}</p></div><i></i><div><span>02</span><strong>权益目标</strong><p>${percent(snapshot.risk.confirmedEquityTarget)}</p></div><i></i><div><span>03</span><strong>五资产配置</strong><p>已确认</p></div></div>
      <div class="page-links"><a class="primary-link" href="${root}allocation/index.html">查看目标配置 →</a><a href="${root}portfolio/index.html">对照当前持仓</a><a href="${root}model/index.html">阅读完整风控模型</a></div>
    </section>`;
}

function targetReason(asset: PublicAsset): string {
  const signals = asset.confirmedSignals;
  if (asset.assetClass === 'EQUITY') {
    return `确认日趋势 ${number(signals.trendScore)}、相对强弱 ${number(signals.relativeStrength)}、波动惩罚 ${number(signals.volPenalty)}，形成吸引力 ${number(asset.targetFormation.attractiveness, 3)}；经权益内部上下限归一化后占权益仓 ${percent(asset.targetFormation.finalGroupShare)}。`;
  }
  return `确认日趋势 ${number(signals.trendScore)}；黄金与国债按防御公式分配，最终占防御仓 ${percent(asset.targetFormation.finalGroupShare)}，并满足组合绝对上下限。`;
}

function renderAllocation(context: PageContext): string {
  const { snapshot, advice, root } = context;
  const equity = snapshot.risk.confirmedEquityTarget;
  const defense = 1 - equity;
  const amountBasis = advice.available ? advice.totalValue : 100000;
  const amountBasisLabel = advice.available ? `按本机组合总值 ${money(amountBasis)}` : '按每 10 万元组合示例';
  const colors = ['target-a', 'target-b', 'target-c', 'target-d', 'target-e'];
  const segments = snapshot.assets.map((asset, index) => `<span class="${colors[index]}" style="width:${asset.confirmedTarget * 100}%" aria-label="${escapeHtml(asset.name)} ${percent(asset.confirmedTarget)}"><i>${asset.confirmedTarget >= .09 ? percent(asset.confirmedTarget) : ''}</i></span>`).join('');
  const legend = snapshot.assets.map((asset, index) => `<div><i class="${colors[index]}"></i><span>${escapeHtml(asset.name)}<small>${asset.code}</small></span><strong>${percent(asset.confirmedTarget)}</strong></div>`).join('');
  const rows = snapshot.assets.map((asset, index) => {
    const delta = asset.confirmedTarget - asset.strategicWeight;
    const formation = asset.targetFormation;
    const bound = formation.boundScope === 'EQUITY_INTERNAL'
      ? `权益内部 ${percent(formation.floor)}—${percent(formation.cap)}`
      : `组合绝对 ${percent(formation.floor)}—${percent(formation.cap)}`;
    return `<article class="target-row reveal"><div class="target-identity"><i class="${colors[index]}"></i><div><strong>${escapeHtml(asset.name)}</strong><span>${asset.code} · ${escapeHtml(asset.role)}</span></div></div><div class="target-number"><strong>${percent(asset.confirmedTarget)}</strong><span>战略 ${percent(asset.strategicWeight)} · <b class="${delta > 0 ? 'positive' : delta < 0 ? 'negative' : ''}">${delta >= 0 ? '+' : ''}${percent(delta)}</b></span></div><div class="target-cash"><strong>约 ${money(asset.confirmedTarget * amountBasis)}</strong><span>${amountBasisLabel}</span></div><div class="target-explain"><p>${targetReason(asset)}</p><span>${bound}</span></div></article>`;
  }).join('');
  const model = snapshot.allocationModel;
  return `<section class="allocation-hero reveal"><div><p class="eyebrow">NORTH STAR · ${snapshot.meta.confirmedSignalDate} 月末确认</p><h1>目标配置</h1><p>这是风险模型当前希望长期组合达到的五资产比例。它是衡量持仓偏差的基准，不是要求立即成交的订单。</p><div class="signal-stamp"><i></i><span><strong>Close T 计算，T+1 起使用</strong> · 月内临时目标不进入本页</span></div></div><div class="allocation-north-star"><span>权益总目标</span><strong>${percent(equity)}</strong><p>防御资产 ${percent(defense)}</p><small>确认风险评分 ${number(snapshot.risk.confirmedScore * 100, 1)} / 100</small></div></section>
    <section class="target-board"><div class="target-board-head"><div><p class="eyebrow">五只 ETF 最终目标</p><h2>每一元资金如何分配</h2></div><p>${amountBasisLabel}。金额仅用于理解配置规模，不构成交易建议。</p></div><div class="allocation-bar" role="img" aria-label="五只 ETF 月末确认目标权重">${segments}</div><div class="allocation-legend">${legend}</div></section>
    <section class="section"><div class="section-head reveal"><div><p class="eyebrow">目标明细</p><h2>比例、金额与形成原因</h2></div><p>战略权重提供长期锚点，确认日信号只做有边界的偏移。所有五只资产最终权重严格合计 100%。</p></div><div class="target-list">${rows}</div></section>
    <section class="section"><div class="section-head reveal"><div><p class="eyebrow">形成路径</p><h2>目标比例如何确定</h2></div><p>先由风险评分确定权益总量，再分别处理权益内部排序和防御资产分配。执行层溢价门控不会改变这里的目标。</p></div>
      <div class="formation-steps"><article><span>01 · 风险总量</span><strong>确认评分 ${percent(snapshot.risk.confirmedScore)}</strong><p>${percent(model.riskWeights.trend)} 趋势广度 + ${percent(model.riskWeights.volatility)} 波动评分 + ${percent(model.riskWeights.drawdown)} 回撤评分，得到确认风险评分。三项确认值分别为 ${percent(snapshot.risk.confirmedTrendBreadth)}、${percent(snapshot.risk.confirmedVolScore)}、${percent(snapshot.risk.confirmedDDScore)}。</p></article><article><span>02 · 权益目标</span><strong>${percent(model.baseEquityTotal)} × (${percent(model.coreRatio)} + ${percent(1 - model.coreRatio)} × R)</strong><p>把风险评分映射为 ${percent(equity)} 权益仓，并强制限制在 ${percent(model.equityMin)}—${percent(model.equityMax)}；不加杠杆，也不会降至零权益。</p></article><article><span>03 · 权益内部</span><strong>战略份额 × exp(趋势 + 强弱 − 波动惩罚)</strong><p>系数来自配置：趋势 ${number(model.attractivenessWeights.trend)}、相对强弱 ${number(model.attractivenessWeights.relativeStrength)}、波动惩罚 ${number(model.attractivenessWeights.volPenalty)}。之后执行迭代式上下限归一化。</p></article><article><span>04 · 防御分配</span><strong>${percent(defense)} 分配给黄金与国债</strong><p>黄金从防御仓基准 ${percent(model.defense.goldBaseShare)} 出发，由黄金趋势和国债趋势调整，并同时满足防御内部及组合绝对边界；剩余资金归国债。</p></article></div>
      <div class="page-links"><a class="primary-link" href="${root}portfolio/index.html">对照当前持仓与建议 →</a><a href="${root}model/index.html#8-权益内部配置">阅读完整配置公式</a></div>
    </section>`;
}

function assetRow(asset: PublicAsset, advice: AdviceResult): string {
  const current = advice.available ? advice.currentWeights[asset.code] : null;
  const gap = current == null ? null : asset.confirmedTarget - current;
  return `<tr data-code="${asset.code}" tabindex="0"><td><strong>${escapeHtml(asset.name)}</strong><span>${asset.code} · ${escapeHtml(asset.role)}</span></td><td>${percent(asset.return63)}</td><td>${percent(asset.return126)}</td><td>${percent(asset.return252)}</td><td>${percent(asset.forecastVol)}</td><td>${asset.relativeStrength == null ? '—' : number(asset.relativeStrength, 2)}</td><td>${percent(current)}</td><td><strong>${percent(asset.confirmedTarget)}</strong></td><td class="${gap != null && gap > 0 ? 'positive' : gap != null && gap < 0 ? 'negative' : ''}">${percent(gap)}</td></tr>`;
}

function adviceMarkup(snapshot: PublicSnapshot, advice: AdviceResult): string {
  if (snapshot.health.blocking) return '<div class="decision-note blocked"><strong>暂停建议</strong><p>数据健康检查未通过。请等待数据恢复，勿依据本次页面新增交易。</p></div>';
  if (!advice.available) return '<div class="decision-note"><strong>先录入本机持仓</strong><p>页面已显示模型目标；录入当前市值后，才会计算免交易带、50% 部分再平衡和建议金额。</p><button class="text-button" data-open-portfolio>录入持仓 →</button></div>';
  const active = advice.rows.filter((row) => row.action !== 'NO TRADE');
  if (!active.length) return '<div class="decision-note calm"><strong>NO TRADE · 无需操作</strong><p>所有资产均在免交易区间内。忽略细小偏差有助于控制成本和换手。</p></div>';
  return `<div class="advice-list">${advice.rows.map((row) => `<article class="advice-row ${row.action === 'NO TRADE' ? 'muted' : ''}"><div><span>${row.code}</span><strong>${row.action === 'BUY' ? '建议增加' : row.action === 'SELL' ? '建议降低' : '无需操作'}</strong></div><b class="${row.tradeWeight > 0 ? 'positive' : row.tradeWeight < 0 ? 'negative' : ''}">${money(row.suggestedAmount)}</b><p>当前 ${percent(row.currentWeight)} → 目标 ${percent(row.targetWeight)}；免交易带 ${percent(row.band)}。${escapeHtml(row.reason)}</p></article>`).join('')}</div>`;
}

function renderPortfolio(context: PageContext): string {
  const { snapshot, advice, portfolio } = context;
  const updated = advice.available ? date(portfolio.updatedAt, true) : '尚未录入';
  return `<section class="page-intro reveal"><p class="eyebrow">LAYER 05 · 人工执行</p><h1>持仓与建议</h1><p>把本机持仓与已确认目标对照，只回答是否需要人工再平衡。目标比例的形成过程已独立到目标配置页。</p><div class="page-links"><button class="primary" data-open-portfolio>${advice.available ? '更新本机持仓' : '录入本机持仓'}</button><a href="${context.root}allocation/index.html">查看目标配置依据</a></div></section>
    <section class="section first"><div class="metric-strip reveal"><div><span>组合总值</span><strong>${advice.available ? money(advice.totalValue) : '待录入'}</strong><small>更新：${updated}</small></div><div><span>当前权益</span><strong>${advice.available ? percent(advice.currentEquity) : '—'}</strong><small>含三只权益 ETF</small></div><div><span>月末确认权益目标</span><strong>${percent(snapshot.risk.confirmedEquityTarget)}</strong><small>${snapshot.meta.confirmedSignalDate}</small></div><div><span>月内临时目标</span><strong>${percent(snapshot.risk.provisionalEquityTarget)}</strong><small>仅观察</small></div></div>
      <div class="section-head reveal"><div><p class="eyebrow">目标分解</p><h2>五只 ETF 的当前位置</h2></div><p>点击或按 Enter 选择资产，查看它在组合中的作用、信号和确认目标。</p></div>
      <div class="table-scroll table-edge"><table class="asset-table"><thead><tr><th>资产与角色</th><th>3个月</th><th>6个月</th><th>12个月</th><th>预测波动</th><th>相对强弱</th><th>当前</th><th>目标</th><th>差额</th></tr></thead><tbody>${snapshot.assets.map((asset) => assetRow(asset, advice)).join('')}</tbody></table></div><aside id="asset-inspector" class="asset-inspector" aria-live="polite"></aside>
    </section>
    <section class="section"><div class="section-head reveal"><div><p class="eyebrow">人工执行建议</p><h2>现在需要行动吗</h2></div><p>只采用已完成月末目标，偏差必须越过免交易带；普通建议只修复 50% 缺口，并满足自融资约束。</p></div>
      <div class="advice-meta reveal"><span>可用现金 <strong>${advice.available ? money(portfolio.cash) : '—'}</strong></span><span>513100 溢价门控 <strong class="${advice.premiumStatus === 'RED WARNING' ? 'negative' : ''}">${escapeHtml(advice.premiumStatus)}</strong></span><span>建议性质 <strong>人工复核，不执行交易</strong></span></div>${adviceMarkup(snapshot, advice)}
    </section>
    <section class="section compact"><div class="section-head reveal"><div><p class="eyebrow">执行边界</p><h2>溢价门控不改风险模型</h2></div><p>513100 的人工溢价只限制计划买入：1.5% 起减半，3% 起禁止新增，5% 起红色警告；门控不主动卖出。</p></div>
      <div class="gate-scale" aria-label="QDII 溢价门控阈值"><span>正常<br><b>&lt; 1.5%</b></span><span>买入减半<br><b>1.5%—3%</b></span><span>禁止新增<br><b>3%—5%</b></span><span>红色警告<br><b>≥ 5%</b></span></div>
      ${advice.available ? '<button class="danger-link" data-clear-portfolio>清除本机持仓数据</button>' : ''}
    </section>`;
}

function renderModel(context: PageContext): string {
  if (!context.model) return '<section class="page-intro"><h1>风控模型</h1><p>模型文档载入失败。</p></section>';
  const toc = context.model.headings.filter((heading) => heading.level === 2).map((heading) => `<a href="#${heading.id}">${escapeHtml(heading.text.replace(/^\d+\.\s*/, ''))}</a>`).join('');
  return `<section class="page-intro model-intro reveal"><p class="eyebrow">MODEL MANUAL · 唯一文档源</p><h1>风险封控模型</h1><p>从数据异常到人工执行，逐层说明每个模型的公式、意义、约束和失效处理。页面内容由仓库 Markdown 原文生成。</p><div class="page-links"><a class="primary-link" href="${context.root}data/risk-control-models.md" download>下载 Markdown</a><a href="${context.root}data/index.html">查看当前数据验证</a></div></section>
    <section class="model-summary"><div><span>01</span><strong>数据健康</strong><p>输入不可信就阻断建议</p></div><div><span>02</span><strong>风险预算</strong><p>趋势、波动与回撤合成</p></div><div><span>03</span><strong>目标配置</strong><p>有边界地分配五只 ETF</p></div><div><span>04</span><strong>信号确认</strong><p>月末确认，T+1 使用</p></div><div><span>05</span><strong>人工执行</strong><p>免交易带与部分再平衡</p></div></section>
    <section class="document-layout"><aside class="document-toc"><p>文档目录</p><nav aria-label="模型文档目录">${toc}</nav><a href="#main">返回顶部 ↑</a></aside><article class="markdown-body">${context.model.html}</article></section>`;
}

function backtestMarkup(snapshot: PublicSnapshot, root: string): string {
  if (snapshot.backtest.status !== 'OK') return '<p class="empty">回测尚未生成。</p>';
  const rows = snapshot.backtest.strategies.map((strategy) => `<tr class="${strategy.key === 'D_FRAIS_V1' ? 'selected' : ''}"><td><strong>${escapeHtml(strategy.label)}</strong></td><td>${percent(strategy.metrics.cagr)}</td><td>${percent(strategy.metrics.annualVolatility)}</td><td>${percent(strategy.metrics.maxDrawdown)}</td><td>${number(strategy.metrics.sharpe)}</td><td>${number(strategy.metrics.sortino)}</td><td>${number(strategy.metrics.calmar)}</td><td>${percent(strategy.metrics.turnover)}</td><td>${number(strategy.metrics.tradeCount, 0)}</td><td>${number(strategy.metrics.recoveryDays, 0)}</td></tr>`).join('');
  const frais = snapshot.backtest.strategies.find((strategy) => strategy.key === 'D_FRAIS_V1');
  return `<div class="metric-strip"><div><span>回测区间</span><strong class="small-value">${snapshot.backtest.period.start}<br>${snapshot.backtest.period.end}</strong></div><div><span>交易成本</span><strong>${percent(snapshot.backtest.costRate, 2)}</strong><small>敏感性含 5 / 10 / 20bp</small></div><div><span>参数组合</span><strong>${snapshot.backtest.robustness.cases}</strong><small>不搜索最优单点</small></div><div><span>稳健性</span><strong class="${snapshot.backtest.robustness.warning ? 'warning' : 'positive'}">${snapshot.backtest.robustness.warning ? '过拟合警告' : '通过'}</strong><small>通过率 ${percent(snapshot.backtest.robustness.passRate)}</small></div></div>
    <div class="nav-plot">${frais ? sparkline(frais.nav, 'FRAIS V1 历史净值曲线') : ''}<span>FRAIS V1 历史净值 · 仅供同口径比较</span></div>
    <div class="table-scroll table-edge"><table class="metrics-table"><thead><tr><th>策略</th><th>CAGR</th><th>年化波动</th><th>最大回撤</th><th>Sharpe</th><th>Sortino</th><th>Calmar</th><th>年换手</th><th>交易次数</th><th>恢复天数</th></tr></thead><tbody>${rows}</tbody></table></div>
    <p class="method-note">系统不按历史收益最高选择参数。稳健性只检验合理参数区域的回撤控制是否具有广泛支持；完整结果可<a href="${root}data/parameter-sensitivity.csv" download>下载参数敏感性 CSV</a>。</p>`;
}

function renderData(context: PageContext): string {
  const { snapshot, root } = context;
  const commonStart = Object.values(snapshot.provenance).map((source) => source.firstDate).filter(Boolean).sort().at(-1) ?? '—';
  const commonEnd = Object.values(snapshot.provenance).map((source) => source.lastDate).filter(Boolean).sort().at(0) ?? '—';
  const providerRows = Object.entries(snapshot.provenance).map(([code, source]) => `<tr><td><strong>${code}</strong></td><td>${escapeHtml(source.source)}</td><td>${escapeHtml(source.firstDate ?? '—')}</td><td>${escapeHtml(source.lastDate ?? '—')}</td><td>${escapeHtml(source.observations ?? '—')}</td><td>${source.calendarFillCount ? `${source.calendarFillCount} · ${escapeHtml(source.calendarFilledDates?.join('、') ?? '')}` : '0'}</td></tr>`).join('');
  const issueMarkup = snapshot.health.issues.length ? `<div class="issue-list">${snapshot.health.issues.map((issue) => `<p><strong>${escapeHtml(issue.label)}</strong><span>${escapeHtml(issue.code)} · ${escapeHtml(issue.details)}</span></p>`).join('')}</div>` : '<p class="health-pass">Missing Date、Duplicate Date、Zero / Negative Price、Abnormal Jump、Stale Data 与 Provider Error 均未发现阻断问题。</p>';
  return `<section class="page-intro reveal"><p class="eyebrow">LAYER 01 · DATA & AUDIT</p><h1>数据与验证</h1><p>先证明输入与时序可信，再讨论历史表现。所有公开结果都可以下载复核，私人持仓不会进入这些文件。</p></section>
    <section class="health-banner ${snapshot.health.blocking ? 'blocked' : ''}"><div><span>${snapshot.health.blocking ? 'DATA ERROR' : 'DATA OK'}</span><strong>${snapshot.health.blocking ? '新建议闸门关闭' : '新建议闸门开放'}</strong></div><p>${escapeHtml(snapshot.health.summary)}</p><small>生成于 ${date(snapshot.meta.generatedAt, true)}</small></section>
    <section class="section first"><div class="section-head reveal"><div><p class="eyebrow">数据健康</p><h2>先看输入，再看结论</h2></div><p>五只 ETF 使用前复权收盘价，并在共同交易日历上对齐。孤立停牌日只有留下审计记录后才允许填充。</p></div>
      <div class="audit-strip"><div><span>共同可用区间</span><strong>${commonStart} → ${commonEnd}</strong></div><div><span>价格约定</span><strong>${escapeHtml(snapshot.meta.priceConvention)}</strong></div><div><span>配置指纹</span><strong class="mono">${escapeHtml(snapshot.meta.configFingerprint)}</strong></div><div><span>时序纪律</span><strong>Close T → Position T+1</strong></div></div>${issueMarkup}
      <div class="table-scroll table-edge"><table class="provider-table"><thead><tr><th>ETF</th><th>来源</th><th>首日</th><th>末日</th><th>原始观测</th><th>审计填充</th></tr></thead><tbody>${providerRows}</tbody></table></div>
    </section>
    <section class="section"><div class="section-head reveal"><div><p class="eyebrow">独立验证 · T+1</p><h2>回测与参数稳健性</h2></div><p>A / B / C / D 统一使用复权价格、下一交易日持仓和显式成本。比较用来理解风险—收益—换手权衡，不用来挑最高 CAGR。</p></div>${backtestMarkup(snapshot, root)}</section>
    <section class="section compact"><div class="section-head reveal"><div><p class="eyebrow">公开文件</p><h2>下载并复核</h2></div><p>这些文件只包含公开行情和模型输出。浏览器本机持仓、现金、溢价与备份密码不会被打包。</p></div>
      <div class="download-list"><a href="${root}data/snapshot.json" download><span>JSON</span><strong>风险与目标快照</strong><small>页面使用的数据契约</small></a><a href="${root}data/adjusted-prices.csv" download><span>CSV</span><strong>前复权价格</strong><small>五只 ETF 公共日历</small></a><a href="${root}data/parameter-sensitivity.csv" download><span>CSV</span><strong>参数敏感性</strong><small>81 组参数区域</small></a><a href="${root}data/risk-control-models.md" download><span>MD</span><strong>风控模型文档</strong><small>公式、边界与失效处理</small></a></div>
    </section>`;
}

export function renderPage(context: PageContext): string {
  if (context.page === 'allocation') return renderAllocation(context);
  if (context.page === 'portfolio') return renderPortfolio(context);
  if (context.page === 'model') return renderModel(context);
  if (context.page === 'data') return renderData(context);
  return renderRisk(context);
}
