import type { LocalPortfolio } from './types';
import { emptyPortfolio } from './rebalance';

const DATABASE = 'fraiss-v3-private';
const STORE = 'portfolio';
const KEY = 'current';

function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DATABASE, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function loadPortfolio(): Promise<LocalPortfolio> {
  try {
    const database = await openDatabase();
    return await new Promise((resolve, reject) => {
      const request = database.transaction(STORE).objectStore(STORE).get(KEY);
      request.onsuccess = () => resolve((request.result as LocalPortfolio | undefined) ?? emptyPortfolio());
      request.onerror = () => reject(request.error);
    });
  } catch {
    const fallback = localStorage.getItem(DATABASE);
    return fallback ? JSON.parse(fallback) as LocalPortfolio : emptyPortfolio();
  }
}

export async function savePortfolio(portfolio: LocalPortfolio): Promise<void> {
  try {
    const database = await openDatabase();
    await new Promise<void>((resolve, reject) => {
      const request = database.transaction(STORE, 'readwrite').objectStore(STORE).put(portfolio, KEY);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch {
    localStorage.setItem(DATABASE, JSON.stringify(portfolio));
  }
}
